//! Every Vim command, from Vim's own index (`:help index`), and how much of
//! it Flow Buddy teaches and coaches. Generated by `scripts/vim-index.py`;
//! what's left out on purpose, and why, is in `data/vim-skip.tsv`.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use crate::curriculum::{items_of_keys, rule_skills};
use crate::key::{Key, Mods, Sym};

/// One command from Vim's index.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Entry {
    /// insert, normal, visual, cmdline, terminal or ex.
    pub mode: &'static str,
    /// Where in the index: text-objects, windows, g, z, brackets…
    pub section: &'static str,
    /// Its help tag: `v_iw`, `CTRL-W_j`, `:sort`.
    pub tag: &'static str,
    /// As the index writes it: `["x]d{motion}`, `:sor[t]`.
    pub keys: &'static str,
    pub what: &'static str,
}

static DATA: &str = include_str!("../data/vim-index.tsv");
static SKIP: &str = include_str!("../data/vim-skip.tsv");

/// Vim's index, parsed once.
pub fn entries() -> &'static [Entry] {
    static ENTRIES: OnceLock<Vec<Entry>> = OnceLock::new();
    ENTRIES.get_or_init(|| {
        DATA.lines()
            .filter(|l| !l.starts_with('#'))
            .skip(1)
            .filter_map(|l| {
                let mut f = l.splitn(5, '\t');
                let (mode, section, tag, keys, what) =
                    (f.next()?, f.next()?, f.next()?, f.next()?, f.next()?);
                // Normal-mode rows start with a note: 1 moves the cursor,
                // 2 can be undone.
                let what = what.trim_start_matches(['1', '2']).trim_start();
                Some(Entry {
                    mode,
                    section,
                    tag,
                    keys,
                    what,
                })
            })
            .collect()
    })
}

/// Why a command is left out on purpose, if it is.
pub fn skipped(e: &Entry) -> Option<&'static str> {
    SKIP.lines()
        .filter(|l| !l.starts_with('#'))
        .filter_map(|l| l.split_once('\t'))
        .find(|(_, tags)| {
            tags.split(' ').any(
                |t| match t.strip_prefix('%').and_then(|t| t.strip_suffix('%')) {
                    Some(word) => e.tag.contains(word),
                    None => t == e.tag,
                },
            )
        })
        .map(|(why, _)| why)
}

/// A key by its name in the index: `CR`, `C-End`, `S-Left`.
fn special(name: &str) -> Option<Key> {
    let (mods, base) = match name.split_once('-') {
        Some(("C", b)) => (
            Mods {
                ctrl: true,
                ..Mods::NONE
            },
            b,
        ),
        Some(("S", b)) => (
            Mods {
                shift: true,
                ..Mods::NONE
            },
            b,
        ),
        _ => (Mods::NONE, name),
    };
    let sym = match base {
        "CR" | "NL" => Sym::Enter,
        "Esc" => Sym::Esc,
        "Tab" => Sym::Tab,
        "BS" => Sym::Backspace,
        "Del" => Sym::Delete,
        "Insert" => Sym::Insert,
        "Up" => Sym::Up,
        "Down" => Sym::Down,
        "Left" => Sym::Left,
        "Right" => Sym::Right,
        "Home" => Sym::Home,
        "End" => Sym::End,
        "PageUp" => Sym::PageUp,
        "PageDown" => Sym::PageDown,
        "Space" => Sym::Char(' '),
        _ => return None,
    };
    Some(Key { sym, mods })
}

/// What to type for a placeholder: `{motion}` → `w`, `{char}` → `x`.
fn placeholder(name: &str) -> Option<&'static str> {
    Some(match name {
        "motion" => "w",
        "char" | "char1" | "pattern" => "x",
        "char2" => "y",
        "count" | "height" | "filter" | "mode" => "",
        // Registers and marks: any letter does.
        _ if name.contains("a-z") || name.contains("A-Z") => "a",
        "regname" | "register" | "mark" => "a",
        _ => return None,
    })
}

/// The keys to type for an index entry, from Normal mode: `["x]d{motion}`
/// → `dw`, `CTRL-W j` → Ctrl-w then j, `<C-End>`. Insert-mode keys come
/// after `i`, Visual ones after `v`, text objects after `d`,
/// command-line keys after `:`.
fn keys_of(e: &Entry) -> Option<Vec<Key>> {
    let mut out = Vec::new();
    match (e.mode, e.section) {
        ("insert", _) => out.push(Key::ch('i')),
        ("visual", _) => out.push(Key::ch('v')),
        ("cmdline", _) => out.push(Key::ch(':')),
        ("normal", "text-objects") | ("operator-pending", _) => out.push(Key::ch('d')),
        // Terminal-job mode reads keys like Insert mode does.
        ("terminal", _) => out.push(Key::ch('i')),
        ("ex", _) => return None,
        _ => {}
    }
    let start = out.len();
    // Entries whose keys need something after them to mean anything.
    let keys = match e.tag {
        "quote" => "\"ayy",
        "<Tab>" => "CTRL-I",
        "N:" => ":.,+2d<CR>",
        // On a selection, `:` and `!` start with its range filled in; the
        // tracker sees only what's typed after.
        "v_:" => ":'<,'>d<CR>",
        "v_!" => "!!",
        // Visual versions of Normal-mode lookups.
        "c_wildchar" => "<Tab>",
        "v_r" => "rx",
        "t_CTRL-W_N" | "t_CTRL-W_:" => "CTRL-\\ CTRL-N",
        "v_K" => "K",
        "v_CTRL-]" => "CTRL-]",
        _ => e.keys,
    };
    let mut rest = keys.replace("[\"x]", "").replace("[count]", "");
    // A count first: `N%`, `N<Del>`.
    if rest.len() > 1 && rest.starts_with('N') {
        rest.remove(0);
    }
    let mut chars = rest.as_str();
    while let Some(c) = chars.chars().next() {
        if let Some(r) = chars.strip_prefix("CTRL-") {
            let k = r.chars().next()?;
            out.push(Key::ctrl(k.to_ascii_lowercase()));
            chars = &r[k.len_utf8()..];
        } else if c == '<'
            && let Some(end) = chars.find('>')
            && end > 1
            && let Some(k) = special(&chars[1..end])
        {
            out.push(k);
            chars = &chars[end + 1..];
        } else if c == '{'
            && let Some(end) = chars.find('}')
            && end > 1
            && let Some(text) = placeholder(&chars[1..end])
        {
            out.extend(text.chars().map(Key::ch));
            chars = &chars[end + 1..];
        } else if c == ' ' && chars.len() > 1 {
            // Keys are spaced apart: `CTRL-W j`, `g CTRL-A`.
            chars = &chars[1..];
        } else if (c == '<' && chars[1..].starts_with(|c: char| c.is_ascii_uppercase()))
            || (c == '{' && chars.len() > 1)
        {
            // A key not worth typing (<F1>, mouse keys) or an unknown
            // placeholder.
            return None;
        } else {
            out.push(Key::ch(c));
            chars = &chars[c.len_utf8()..];
        }
    }
    (out.len() > start).then_some(out)
}

/// An Ex command's name as typed: `:sor[t]` → `sort`.
fn ex_name(e: &Entry) -> Option<String> {
    let k = e.keys.trim_start_matches(':');
    let name: String = k
        .split_whitespace()
        .next()?
        .chars()
        .filter(|c| !matches!(c, '[' | ']'))
        .collect();
    (!name.is_empty() && !name.contains('{')).then_some(name)
}

/// Ex commands are typed in many ways (`:s/a/b/`, `:g/x/d`, `:b 2`): try
/// a few, in both the short and the full spelling.
fn ex_items(e: &Entry) -> Vec<&'static str> {
    // `:42`: a line number on its own is the command.
    if e.tag == ":range" {
        let keys: Vec<Key> = ":42".chars().map(Key::ch).chain([Key::ENTER]).collect();
        return items_of_keys(&keys);
    }
    let full = ex_name(e);
    let short = e
        .keys
        .trim_start_matches(':')
        .split('[')
        .next()
        .filter(|s| !s.is_empty() && !s.contains(['{', ' ']))
        .map(String::from);
    for name in [short, full].into_iter().flatten() {
        for typed in [name.clone(), format!("{name}/x/y/"), format!("{name} x")] {
            let mut keys = vec![Key::ch(':')];
            keys.extend(typed.chars().map(Key::ch));
            keys.push(Key::ENTER);
            let items = items_of_keys(&keys);
            if !items.is_empty() {
                return items;
            }
        }
    }
    Vec::new()
}

/// What Flow Buddy does with one command.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Covered {
    /// A rule can spot when you'd want it, and the curriculum teaches it.
    Coached,
    /// The curriculum teaches it; no rule spots the need.
    Taught,
    /// Where everyone starts; rules coach you past it.
    Starting,
    /// Left out on purpose, for this reason.
    Skipped(&'static str),
    /// Not yet.
    No,
}

/// What you start with, by help tag: Flow Buddy coaches you on from these
/// rather than teaching them. Arrow keys and the like are what the arrow
/// rules coach you away from.
const STARTING: &[&str] = &[
    "h",
    "j",
    "k",
    "l",
    "i",
    "a",
    "v",
    "x",
    "u",
    ":",
    "q",
    "ZQ",
    "<Left>",
    "<Right>",
    "<Up>",
    "<Down>",
    "<Home>",
    "<End>",
    "<BS>",
    "<Space>",
    "<Del>",
    "<Insert>",
    "<PageUp>",
    "<PageDown>",
    "i_<BS>",
    "i_<CR>",
    "i_<Esc>",
    "i_<Tab>",
    "i_<Del>",
    "i_<Left>",
    "i_<Right>",
    "i_<Up>",
    "i_<Down>",
    "i_<Home>",
    "i_<End>",
    "i_<PageUp>",
    "i_<PageDown>",
    "i_<C-Home>",
    "i_<C-End>",
    "i_<S-Left>",
    "i_<S-Right>",
    "i_<C-Left>",
    "i_<C-Right>",
    "i_<S-Up>",
    "i_<S-Down>",
    "c_<CR>",
    "c_<Esc>",
    "c_<BS>",
    "c_<Del>",
    "c_<Left>",
    "c_<Right>",
    "c_<Home>",
    "c_<S-Left>",
    "c_<C-Left>",
    "c_<S-Right>",
    "c_<C-Right>",
    "c_<End>",
    "v_<Esc>",
    "v_v",
    "v_d",
    "v_y",
    "v_c",
    "v_x",
    "<CR>",
    "count",
];

/// The command an alias stands for: `same as "CTRL-W b"`, `synonym for
/// "yy"`, `same as |:|`.
fn alias_target(what: &str) -> Option<&str> {
    let rest = what
        .strip_prefix("same as ")
        .or_else(|| what.split_once("synonym for ").map(|(_, r)| r))?;
    match rest.chars().next()? {
        q @ ('"' | '`' | '|') => {
            let body = &rest[1..];
            Some(&body[..body.find(q)?])
        }
        _ => Some(rest.split([',', ';']).next()?.split(" (").next()?.trim()),
    }
}

fn find_alias(e: &Entry) -> Option<&'static Entry> {
    let target = alias_target(e.what)?;
    let strip = |k: &str| k.replace("[\"x]", "").replace("[count]", "");
    entries().iter().find(|t| {
        !std::ptr::eq(*t, e)
            && match target.strip_prefix(':').filter(|r| !r.is_empty()) {
                Some(ex) => t.mode == "ex" && t.tag.trim_start_matches(':') == ex,
                // A terminal window's aliases are Normal-mode commands.
                None => {
                    (t.mode == e.mode || (e.mode == "terminal" && t.mode == "normal"))
                        && strip(t.keys) == target
                }
            }
    })
}

pub fn covered(e: &Entry) -> Covered {
    covered_at(e, 0)
}

fn covered_at(e: &Entry, depth: u8) -> Covered {
    if e.mode != "ex" && STARTING.contains(&e.tag) {
        return Covered::Starting;
    }
    if let Some(why) = skipped(e) {
        return Covered::Skipped(why);
    }
    let items = match e.mode {
        "ex" => ex_items(e),
        _ => keys_of(e).map(|k| items_of_keys(&k)).unwrap_or_default(),
    };
    if items.is_empty() {
        // An alias is covered as what it stands for.
        return match find_alias(e).filter(|_| depth < 3) {
            Some(t) => covered_at(t, depth + 1),
            None => Covered::No,
        };
    }
    let coached = crate::rules::all().iter().any(|r| {
        rule_skills(r.id()).is_some_and(|skills| items.iter().any(|i| skills.contains(i)))
    });
    if coached {
        Covered::Coached
    } else {
        Covered::Taught
    }
}

/// Coverage of one mode.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Tally {
    pub commands: usize,
    pub coached: usize,
    pub taught: usize,
    pub starting: usize,
    pub skipped: usize,
    pub missing: usize,
}

pub fn coverage() -> BTreeMap<&'static str, Tally> {
    let mut out: BTreeMap<&'static str, Tally> = BTreeMap::new();
    for e in entries() {
        let t = out.entry(e.mode).or_default();
        t.commands += 1;
        match covered(e) {
            Covered::Coached => t.coached += 1,
            Covered::Taught => t.taught += 1,
            Covered::Starting => t.starting += 1,
            Covered::Skipped(_) => t.skipped += 1,
            Covered::No => t.missing += 1,
        }
    }
    out
}

/// Commands not covered yet, and not left out on purpose.
pub fn gaps() -> Vec<&'static Entry> {
    entries()
        .iter()
        .filter(|e| covered(e) == Covered::No)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn find(tag: &str) -> &'static Entry {
        entries()
            .iter()
            .find(|e| e.tag == tag)
            .unwrap_or_else(|| panic!("no {tag}"))
    }

    #[test]
    fn reads_vims_index() {
        let all = entries();
        assert!(all.len() > 1200, "{}", all.len());
        let w = find("w");
        assert_eq!((w.mode, w.what), ("normal", "cursor N words forward"));
    }

    #[test]
    fn commands_map_to_what_teaches_them() {
        assert_eq!(covered(find("w")), Covered::Coached);
        assert_eq!(covered(find(":sort")), Covered::Taught);
        assert_eq!(covered(find("v_iw")), Covered::Coached, "diw");
        assert_eq!(covered(find("{")), Covered::Coached, "paragraph");
        assert_ne!(covered(find("N")), Covered::No, "search-back");
        assert_eq!(covered(find("j")), Covered::Starting);
        assert_ne!(covered(find("m")), Covered::No, "m{{A-Za-z}}: marks");
        assert_ne!(covered(find("CTRL-W_h")), Covered::No, "Ctrl-w h");
        assert_ne!(covered(find(":substitute")), Covered::No);
    }

    #[test]
    fn aliases_take_what_they_stand_for() {
        assert_eq!(alias_target(r#"same as "CTRL-W b""#), Some("CTRL-W b"));
        assert_eq!(alias_target("same as CTRL-V, unless used"), Some("CTRL-V"));
        assert_eq!(
            alias_target(r#"yank N lines [into register x]; synonym for "yy""#),
            Some("yy")
        );
        assert_eq!(
            covered(find("CTRL-W_CTRL-H")),
            covered(find("CTRL-W_h")),
            "same as CTRL-W h"
        );
    }

    #[test]
    fn some_are_left_out_on_purpose() {
        assert!(matches!(covered(find("Q")), Covered::Skipped(r) if r.contains("Ex mode")));
        assert!(matches!(covered(find(":lua")), Covered::Skipped(_)));
        assert!(matches!(
            covered(find("<ScrollWheelUp>")),
            Covered::Skipped(_)
        ));
        assert!(skipped(find(":write")).is_none());
        assert!(gaps().iter().all(|e| skipped(e).is_none()));
        // Every command is decided: taught, coached, where you start, or
        // left out with a reason. A new Vim index shows what's new here.
        let left: Vec<_> = gaps().iter().map(|e| e.tag).collect();
        assert!(left.is_empty(), "not covered yet: {left:?}");
    }

    #[test]
    #[ignore]
    fn dump_uncovered() {
        for e in gaps() {
            println!("{}\t{}\t{}\t{}", e.mode, e.tag, e.keys, e.what);
        }
    }
}
